using sv_2a94b70cb6e14a95879a204e98804383.Client.Services;

namespace sv_2a94b70cb6e14a95879a204e98804383.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 14, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 9, 8, 0, 0, TimeSpan.FromHours(-5)), Description = "Package picked up" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 10, 14, 30, 0, TimeSpan.FromHours(-5)), Description = "Arrived at sorting facility — Memphis, TN" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 11, 6, 15, 0, TimeSpan.FromHours(-5)), Description = "Departed facility — en route to Chicago, IL" },
            ]
        },
        ["TRK-002"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-002",
            Status = "Delivered",
            Location = "Austin, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 10, 12, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 7, 9, 0, 0, TimeSpan.FromHours(-5)), Description = "Package picked up" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 8, 11, 0, 0, TimeSpan.FromHours(-5)), Description = "In transit — Dallas, TX" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 9, 16, 45, 0, TimeSpan.FromHours(-5)), Description = "Out for delivery" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 9, 18, 20, 0, TimeSpan.FromHours(-5)), Description = "Delivered — left at front door" },
            ]
        },
        ["TRK-003"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 18, 12, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 11, 10, 0, 0, TimeSpan.FromHours(-7)), Description = "Order confirmed — preparing shipment" },
            ]
        },
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment '{trackingNumber}' not found.");
    }
}

